function next_smallest(lst){
  if (lst.length < 2) return undefined;
  let smallest = lst[0], second_smallest = Infinity;
  for (let i = 1; i < lst.length; i++) {
    if (lst[i] < smallest) {
      second_smallest = smallest;
      smallest = lst[i];
    } else if (lst[i] < second_smallest && lst[i] !== smallest) {
      second_smallest = lst[i];
    }
  }
  return second_smallest === Infinity ? undefined : second_smallest;
}

