function max_sub_array_sum_repeated(a, n, k) {
  let maxSum = 0;
  let currentSum = 0;

  // Calculate the sum of the original array
  for (let i = 0; i < n; i++) {
    currentSum += a[i];
    maxSum = Math.max(maxSum, currentSum);
  }

  // Calculate the sum of the array after repeating k times
  for (let i = 0; i < k; i++) {
    currentSum = 0;
    for (let j = 0; j < n; j++) {
      currentSum += a[j];
    }
    maxSum = Math.max(maxSum, currentSum);
  }

  return maxSum;
}

