        visited[nx][ny] = true;
        let newPath = [...path, grid[nx][ny]];
        let result = dfs(nx, ny, newPath, count + 1);
        if (result.length < minPath.length) {
          minPath = result;
        }
        visited[nx][ny] = false;
      }
    }

    return minPath;
  }

