function strange_sort_list(lst) {
  if (lst.length === 0) return [];
  let sortedList = lst.slice().sort((a, b) => a - b);
  let result = [];
  while (sortedList.length > 0) {
    result.push(sortedList.shift());
    if (sortedList.length > 0) {
      result.push(sortedList.pop());
    }
  }
  return result;
}

